def find_path(graph, start, goal):
    # Initialize open and closed sets
    open_set = {start}
    came_from = {}

    # Initialize cost and parent for start node
    cost = {node: float('infinity') for node in graph}
    cost[start] = 0
    parent = {node: None for node in graph}
    parent[start] = start

    while open_set:
        # Choose the node with the lowest cost
        current = min(open_set, key=lambda node: cost[node])

        # Check if we have reached the goal
        if current == goal:
            return reconstruct_path(came_from, start, goal)

        # Remove the node from the open set
        open_set.remove(current)
        open_set.discard(goal)
        open_set.discard(start)
        open_set.discard(parent[current])

        # Explore the neighbors
        for neighbor in graph[current]:
            if neighbor in open_set or neighbor in closed_set:
                continue

            new_cost = cost[current] + 1  # Assuming all edges have unit weight
            if new_cost < cost[neighbor]:
                cost[neighbor] = new_cost
                parent[neighbor] = current
                if neighbor not in open_set:
                    open_set.add(neighbor)

    # Goal is unreachable
    return None

def reconstruct_path(came_from, start, goal):
    current = goal
    path = [current]
    while current != start:
        current = came_from[current]
        path.append(current)
    path.reverse()
    return path
